const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',play:'m9 5 11 7-11 7z',map:'M12 3v6 M5 15v-6h14v6 M3 15h4v5H3z M10 15h4v5h-4z M17 15h4v5h-4z',image:'M3 3h18v18H3z M3 16l6-6 5 5 3-3 4 4 M16 7h.01',list:'M9 6h12 M9 12h12 M9 18h12 M3 6h1 M3 12h1 M3 18h1',check:'m5 12 4 4L19 6',bug:'M8 8h8v10a4 4 0 0 1-8 0z M9 8V6a3 3 0 0 1 6 0v2 M4 10h4 M16 10h4 M4 15h4 M16 15h4 M6 21l3-3 M18 21l-3-3 M12 9v11',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5 M12 18h.01',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 m-5-5 5 5-5 5',globe:'M21 12A9 9 0 1 1 3 12a9 9 0 0 1 18 0 M3 12h18 M12 3c5 5 5 13 0 18-5-5-5-13 0-18',spark:'m12 3 2 6 6 3-6 2-2 7-2-7-6-2 6-3z M20 2v4 M18 4h4',infinity:'M12 12c-8-13-16 9-6 5l12-10c10-4 2 18-6 5',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16 m6-2 6 6',clock:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18 M12 7v5l3 2',pause:'M8 5v14 M16 5v14',stop:'M5 5h14v14H5z',close:'m6 6 12 12 M6 18 18 6',link:'M9 15l6-6 M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',file:'M5 3h9l5 5v13H5z M14 3v5h5 M8 12h8 M8 16h6',cursor:'m4 3 6 18 3-7 7-3z',refresh:'M20 7a9 9 0 1 0 1 8 M20 2v6h-6',folder:'M3 5h7l2 3h9v13H3z'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const navItems=[['overview','grid','개요'],['runs','play','테스트 실행'],['map','map','화면 탐색 지도'],['screenshots','image','스크린샷'],['features','list','기능 목록'],['cases','check','테스트 케이스'],['defects','bug','결함 리포트']];
const demoPages=[{id:'p1',name:'메인 페이지',url:'https://demo.traceqa.local/',parent:null,elements:12,status:'완료',path:['메인']},{id:'p2',name:'상품 목록',url:'https://demo.traceqa.local/products',parent:'p1',elements:18,status:'완료',path:['메인','상품 목록']},{id:'p3',name:'브랜드 소개',url:'https://demo.traceqa.local/about',parent:'p1',elements:6,status:'완료',path:['메인','브랜드 소개']},{id:'p4',name:'고객 지원',url:'https://demo.traceqa.local/support',parent:'p1',elements:9,status:'완료',path:['메인','고객 지원']},{id:'p5',name:'상품 상세',url:'https://demo.traceqa.local/products/01',parent:'p2',elements:8,status:'완료',path:['메인','상품 목록','상품 상세']},{id:'p6',name:'이미지 확대 모달',url:'https://demo.traceqa.local/products/01',parent:'p5',elements:3,status:'완료',path:['메인','상품 목록','상품 상세','이미지 확대']}];
const demoCases=[{id:'TC-001',name:'상품 목록으로 이동',feature:'상품 탐색',status:'통과',steps:['메인 페이지 접속','상단 상품 메뉴 클릭'],expected:'상품 목록 화면 표시',actual:'목록 화면 및 상품 카드 표시 확인',page:'p2'},{id:'TC-002',name:'상품 상세 페이지 열기',feature:'상품 탐색',status:'통과',steps:['상품 목록 접속','첫 번째 상품 카드 클릭'],expected:'선택한 상품의 상세 정보 표시',actual:'상품명, 이미지, 가격 표시 확인',page:'p5'},{id:'TC-003',name:'상품 이미지 확대',feature:'이미지 보기',status:'통과',steps:['상품 상세 접속','대표 이미지 클릭'],expected:'이미지 확대 모달 표시',actual:'모달 열림과 닫기 버튼 확인',page:'p6'},{id:'TC-004',name:'문의하기 링크 이동',feature:'고객 지원',status:'실패',steps:['고객 지원 접속','문의하기 링크 클릭'],expected:'문의 페이지 정상 응답',actual:'HTTP 404 응답',page:'p4'},{id:'TC-005',name:'모바일 메뉴 닫기',feature:'메뉴 탐색',status:'검토 필요',steps:['메뉴 열기','닫기 아이콘 클릭'],expected:'메뉴 닫힘',actual:'변화가 명확하지 않아 검토 필요',page:'p1'},{id:'TC-006',name:'상품 구매 진행',feature:'구매',status:'제외됨',steps:['상품 상세 접속','구매 버튼 확인'],expected:'별도 허용 필요',actual:'데이터 변경 정책으로 클릭 제외',page:'p5'}];
const demoDefects=[{id:'BUG-001',name:'문의하기 링크에서 404 응답',severity:'높음',status:'검증 실패',page:'p4',expected:'문의 페이지 정상 응답',actual:'HTTP 404 응답',steps:['메인 페이지 접속','고객 지원 클릭','문의하기 클릭'],evidence:'응답 상태: 404 · GET /support/contact'},{id:'BUG-002',name:'메뉴 닫기 후 화면 변화 확인 필요',severity:'검토',status:'결함 후보',page:'p1',expected:'메뉴가 닫히고 본문 조작 가능',actual:'클릭 이후 의미 있는 변화 감지 안 됨',steps:['메인 페이지 접속','메뉴 아이콘 클릭','닫기 아이콘 클릭'],evidence:'화면 차이 분석만으로 결함 확정 불가'}];
const demoFeatures=[{name:'상품 탐색',description:'목록에서 상세 화면까지 이동',pages:2,status:'확인됨',path:'메인 → 상품 목록 → 상품 상세'},{name:'이미지 보기',description:'상품 이미지를 모달로 확대',pages:1,status:'확인됨',path:'상품 상세 → 이미지 확대'},{name:'브랜드 소개',description:'브랜드 소개 콘텐츠 확인',pages:1,status:'확인됨',path:'메인 → 브랜드 소개'},{name:'고객 지원',description:'문의와 지원 페이지 이동',pages:1,status:'오류 발견',path:'메인 → 고객 지원 → 문의하기'},{name:'메뉴 탐색',description:'메뉴 열기와 닫기',pages:1,status:'검토 필요',path:'메인 → 메뉴'},{name:'구매',description:'상품 구매 기능 후보',pages:1,status:'미검증',path:'상품 상세 → 구매'}];
let state={mode:'demo',page:location.hash.slice(1)||'overview',filter:'전체',query:'',selected:'p1',paused:false,sim:false,logs:[],run:null,connected:false,connection:readSettings()};
function readSettings(){try{return JSON.parse(localStorage.getItem('traceqa-settings')||'{}')}catch{return {}}}
function data(){return state.mode==='demo'?{pages:demoPages,cases:demoCases,defects:demoDefects,features:demoFeatures,logs:demoLogs()}:state.run||{pages:[],cases:[],defects:[],features:[],logs:[]}}
function demoLogs(){return [{type:'check',text:'이미지 확대 모달 탐색 완료',detail:'상품 상세 → 이미지 확대',time:'샘플'},{type:'cursor',text:'새로운 조작 요소 3개 발견',detail:'DOM + 화면 분석 · 모달',time:'샘플'},{type:'bug',text:'문의하기 링크 응답 오류',detail:'HTTP 404 · /support/contact',time:'샘플'},{type:'map',text:'상품 상세 화면 기록',detail:'메인 → 상품 목록 → 상품 상세',time:'샘플'}]}
function badge(s){let c=/통과|완료|확인됨|연결됨/.test(s)?'green':/실패|오류|높음/.test(s)?'red':/탐색|실행/.test(s)?'purple':/검토|후보|대기/.test(s)?'orange':'gray';return `<span class="pill ${c}"><i class="tiny-dot"></i>${esc(s)}</span>`}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function go(p){state.page=p;state.query='';state.filter='전체';location.hash=p;render()}
window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(p!==state.page){state.page=p;render()}});
function render(){if(![...navItems.map(x=>x[0]),'settings'].includes(state.page))state.page='overview';$('#nav').innerHTML=navItems.map(([id,i,l])=>`<button data-nav="${id}" class="${state.page===id?'active':''}" title="${l}">${icon(i)}<span>${l}</span>${id==='defects'&&data().defects.length?`<b class="nav-num">${data().defects.length}</b>`:''}</button>`).join('');$('#crumb').textContent=navItems.find(x=>x[0]===state.page)?.[2]||'워커 연결 설정';$('#engineLabel').textContent=state.connected?'연결됨':'연결 대기';$('.pulse').style.background=state.connected?'#c9ef85':'#89958e';$('#main').innerHTML=({overview:overview,runs:runs,map:mapPage,screenshots:screenshots,features:features,cases:cases,defects:defects,settings:settings}[state.page])();bind();$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon))}
const title=(ey,h,sub,actions='')=>`<div class="title-row"><div><div class="eyebrow">${ey}</div><h1>${h}</h1><p class="subtitle">${sub}</p></div><div class="page-tools">${actions}</div></div>`;
const exportBtn=()=>`<button class="btn btn-outline" data-action="export">${icon('download')} 보고서 내보내기</button>`;
const demoBanner=()=>state.mode==='demo'?`<div class="demo-banner">${icon('file')} 샘플 데이터로 보는 워크스페이스입니다. 실제 사이트 테스트 결과가 아닙니다.<button data-action="real">실제 테스트로 전환 ↗</button></div>`:'';
function launch(){return `<section class="panel launch"><div class="launch-heading">${icon('spark')} 어디부터 탐색해 볼까요?</div><p class="launch-desc">시작 주소 하나로, 연결된 화면과 기능을 차근차근 확인하세요.</p><form id="urlForm" class="url-form"><label class="url-input">${icon('globe')}<input id="targetUrl" type="url" placeholder="https://테스트할-웹사이트.com" aria-label="테스트할 웹사이트 URL" required value="${esc(state.target||'')}"></label><button class="btn btn-dark" type="submit">${icon('play')} 테스트 시작</button><button class="btn btn-outline" type="button" data-nav="settings" aria-label="실행 설정">${icon('settings')}</button></form><div class="launch-meta"><span>${icon('infinity')} 깊이 제한 없는 재귀 탐색</span><span>${icon('cursor')} DOM + AI 화면 인식</span><span>${icon('shield')} 데이터 변경 동작 기본 제외</span></div></section>`}
function stats(){let d=data(),els=d.pages.reduce((n,p)=>n+(p.elements||0),0);return `<div class="stats">${[['발견한 화면',d.pages.length,'개','map','고유 화면과 상태 기록'],['조작 요소',els,'개','cursor','버튼 · 링크 · 탭 · 입력'],['테스트 케이스',d.cases.length,'개','check',`${d.cases.filter(c=>c.status==='통과').length}개 통과 · ${d.cases.filter(c=>c.status==='검토 필요').length}개 검토 필요`],['결함 및 후보',d.defects.length,'건','bug',`${d.defects.filter(x=>x.status==='검증 실패').length}건 검증 실패 · 후보 별도 표시`]].map(([l,n,u,i,f])=>`<article class="panel stat"><div class="stat-top">${l}<span class="stat-icon">${icon(i)}</span></div><div class="stat-number">${n}<small>${u}</small></div><div class="stat-bottom">${icon('check').replace('<svg','<svg style="width:11px;height:11px"')} ${f}</div></article>`).join('')}</div>`}
function sessionCard(){let d=data(),sample=state.mode==='demo',run=state.run;return `<section class="panel ${state.paused?'paused':''}"><div class="panel-head"><h2>${sample?'탐색 미리보기':'현재 테스트'}<small>깊이보다 경로에 집중하는 탐색</small></h2><button class="btn btn-text" data-nav="runs">자세히 보기 ${icon('arrow')}</button></div><div class="session-top"><div class="site-logo">${icon('globe')}</div><div><strong>${sample?'보태니컬 스토어 · 샘플':esc(run?.name||'새 테스트를 시작하세요')}</strong><small>${sample?'demo.traceqa.local':esc(run?.url||'워커를 연결하면 실제 탐색이 시작됩니다.')}</small></div>${badge(sample?'샘플':run?.status||'대기')}</div><div class="explore-strip">${sample||run?.status==='실행 중'?'<span class="spinner"></span>':icon('map')}<strong>${sample?'화면을 이해하고, 다음 경로로':esc(run?.current||'아직 실행한 테스트가 없습니다.')}</strong></div><div class="flow-mini">${sample?'<span class="flow-node">메인 페이지</span>→<span class="flow-node">상품 목록</span>→<span class="flow-node current">상품 상세</span>→<span class="flow-node">이미지 확대</span>':d.pages.length?(d.pages.at(-1).path||[]).map((s,i,a)=>`<span class="flow-node ${i===a.length-1?'current':''}">${esc(s)}</span>`).join(' → '):'<span class="flow-node">실행 대기</span>'}</div><div class="session-metrics"><div><strong>${d.pages.length}개</strong>발견한 화면</div><div><strong>${sample?'깊이 제한 없음':run?.status||'실행 전'}</strong>탐색 상태</div><div><strong>${sample?'샘플 경로':(run?.pending??0)+'개'}</strong>${sample?'실제 실행 아님':'남은 작업'}</div></div></section>`}
function activities(){let logs=data().logs||[];return `<section class="panel"><div class="panel-head"><h2>탐색 타임라인<small>행동마다 근거를 남깁니다</small></h2><span class="pill gray">${state.mode==='demo'?'SAMPLE':'LIVE'}</span></div><div class="activity-list">${logs.length?logs.slice(-4).reverse().map((x,i)=>`<div class="activity"><span class="event-icon ${i===1?'purple':i===2?'orange':''}">${icon(x.type||'check')}</span><div class="event-copy"><strong>${esc(x.text)}</strong><small>${esc(x.detail)}</small></div><time>${esc(x.time||'')}</time></div>`).join(''):'<div class="empty">실행 이력이 여기에 표시됩니다.</div>'}</div></section>`}
function overview(){return title('TEST WORKSPACE','놓친 화면 없이, <span>한 단계 더.</span>','웹사이트를 탐색하고, 기능을 확인하고, 결함의 근거를 남기세요.',exportBtn())+launch()+`<div class="section-heading"><h2>워크스페이스 한눈에 <small>${state.mode==='demo'?'샘플 실행 기준':'현재 실행 기준'}</small></h2><span class="demo-note"><i class="tiny-dot"></i>${state.mode==='demo'?'샘플 데이터 · 실제 실행 아님':state.connected?'워커 연결됨':'워커 연결 필요'}</span></div>`+stats()+`<div class="content-grid">${sessionCard()}${activities()}</div>`+recentTable()}
function recentTable(){let rows=state.mode==='demo'?[{name:'보태니컬 스토어',url:'demo.traceqa.local',status:'완료',pages:6,tests:6,defects:2,date:'샘플 실행'}]:state.run?[{name:state.run.name,url:state.run.url,status:state.run.status,pages:data().pages.length,tests:data().cases.length,defects:data().defects.length,date:'현재 실행'}]:[];return `<section class="panel panel-table"><div class="panel-head"><h2>테스트 실행 기록 <span class="badge-count">${rows.length}</span></h2><button class="btn btn-text" data-nav="runs">모든 실행 보기 ${icon('arrow')}</button></div><div class="table-toolbar"><div class="tabs" data-tabs="history">${['전체','완료','실행 중'].map(s=>`<button data-filter="${s}" class="${state.filter===s?'active':''}">${s}</button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="historySearch" placeholder="사이트 검색" aria-label="실행 기록 검색" value="${esc(state.query)}"></label></div><div class="table-wrap"><table><thead><tr><th>테스트 대상</th><th>상태</th><th>화면</th><th>테스트</th><th>결함 / 후보</th><th>실행 시각</th><th></th></tr></thead><tbody id="historyRows">${historyRows(rows)}</tbody></table></div><div class="table-bottom"><span>${state.mode==='demo'?'샘플 데이터입니다. 실제 실행 결과와 구분됩니다.':'현재 브라우저의 최근 실행'}</span><span>총 ${rows.length}개</span></div></section>`}
function historyRows(rows){let filtered=rows.filter(r=>(state.filter==='전체'||r.status===state.filter)&&(`${r.name} ${r.url}`).toLowerCase().includes(state.query.toLowerCase()));return filtered.map(r=>`<tr class="rowclick" data-nav="runs"><td><div class="row-title"><span class="mini-site">${icon('globe')}</span><div>${esc(r.name)}<small>${esc(r.url)}</small></div></div></td><td>${badge(r.status)}</td><td>${r.pages}</td><td>${r.tests}</td><td>${r.defects}</td><td>${r.date}</td><td>↗</td></tr>`).join('')||'<tr><td colspan="7" class="empty">일치하는 실행 기록이 없습니다.</td></tr>'}
function sampleBrowser(){return `<div class="sample-browser"><div class="browser-bar"><i></i><i></i><i></i></div><div class="mini-nav"><b></b><span></span></div><div class="mini-hero"><b></b><b style="width:40%"></b><em></em></div><div class="mini-cards"><div></div><div></div><div></div></div></div>`}
function runs(){let d=data();return title('EXPLORATION','테스트 실행','화면 이해 → 요소 확인 → 실행 → 결과 검증 → 하위 탐색',`<button class="btn btn-outline" data-action="demo">${icon('spark')} 샘플 보기</button>`)+launch()+demoBanner()+`<div class="section-heading"><h2>${state.mode==='demo'?'샘플 실행 미리보기':esc(state.run?.name||'실행 대기')}</h2><div class="inline-actions">${badge(state.mode==='demo'?'샘플':state.run?.status||'대기')}<button class="btn btn-outline btn-sm" data-action="pause" ${!state.sim&&state.mode==='demo'||state.mode==='real'&&!state.run?'disabled':''}>${icon(state.paused?'play':'pause')}${state.paused?'재개':'일시정지'}</button><button class="btn btn-outline btn-sm" data-action="stop" ${!state.sim&&state.mode==='demo'||state.mode==='real'&&!state.run?'disabled':''}>${icon('stop')} 중지</button></div></div><div class="execution"><section class="panel"><div class="panel-head"><h2>현재 화면 <small>${state.mode==='demo'?'화면 표현용 샘플 이미지':esc(state.run?.current||'아직 수집한 화면이 없습니다.')}</small></h2>${state.mode==='demo'?'<button class="btn btn-outline btn-sm" data-action="simulate">흐름 시뮬레이션</button>':''}</div><div class="screen-view">${state.mode==='demo'?sampleBrowser():d.pages.length?`<img src="${esc(screenshotUrl(d.pages.at(-1)))}" alt="최근 탐색 화면">`:'<div class="empty">'+icon('image')+'<p>워커 연결 후 실제 화면을 확인할 수 있습니다.</p></div>'}</div><div class="session-metrics"><div><strong>${d.pages.length}</strong>발견 화면</div><div><strong>${d.cases.length}</strong>실행 기록</div><div><strong>${state.run?.pending??'—'}</strong>남은 작업</div></div></section><section class="panel"><div class="panel-head"><h2>실행 로그<small>화면과 행동의 변화를 기록합니다</small></h2><span class="pill gray">${state.mode==='demo'?'SAMPLE':'LIVE'}</span></div><div class="log-list" id="liveLogs">${(state.sim?state.logs:d.logs).map(x=>`<div class="log-item"><time>${esc(x.time||'')}</time>${esc(x.text)}<div class="muted">${esc(x.detail||'')}</div></div>`).join('')||'<div class="empty">실행 로그가 없습니다.</div>'}</div></section></div>`}
function mapPage(){let d=data(),p=d.pages.find(p=>p.id===state.selected)||d.pages[0];return title('SCREEN GRAPH','화면 탐색 지도','도달한 화면과 상태, 그리고 그 사이의 연결을 확인하세요.',exportBtn())+demoBanner()+(d.pages.length?`<div class="map-layout"><section class="panel map-canvas"><div class="tree">${levels(d.pages).map(level=>`<div class="tree-level">${level.map(n=>`<button class="map-node ${n.id===p.id?'selected':''}" data-node="${esc(n.id)}"><strong>${icon('file')} ${esc(n.name)}</strong><small>${esc(shortPath(n.url))}</small>${badge(n.status)} <span class="muted" style="font-size:9px">요소 ${n.elements}</span></button>`).join('')}</div>`).join('')}</div></section><aside class="panel detail-panel"><div class="eyebrow">SCREEN DETAILS</div><h3>${esc(p.name)}</h3><p>${esc(p.url)}</p>${badge(p.status)}<div class="detail-row"><span>화면 ID</span><strong>${esc(p.id)}</strong></div><div class="detail-row"><span>발견한 요소</span><strong>${p.elements}개</strong></div><div class="detail-row"><span>진입 경로</span><strong>${esc(p.path?.join(' → ')||'메인')}</strong></div><div class="detail-row"><span>인식 방식</span><strong>${state.mode==='demo'?'샘플 정보':esc(p.recognition||'DOM')}</strong></div><button class="btn btn-outline" style="margin-top:20px;width:100%" data-shot="${esc(p.id)}">${icon('image')} 화면 자세히 보기</button></aside></div>`:empty('아직 탐색한 화면이 없습니다.','실제 테스트를 시작하거나 샘플을 확인하세요.'))}
function levels(pages){let out=[],seen=new Set();let current=pages.filter(p=>!p.parent||!pages.some(x=>x.id===p.parent));while(current.length){out.push(current);current.forEach(p=>seen.add(p.id));current=pages.filter(p=>!seen.has(p.id)&&current.some(x=>p.parent===x.id))}let rest=pages.filter(p=>!seen.has(p.id));if(rest.length)out.push(rest);return out}
function shortPath(s){try{return new URL(s).pathname}catch{return s}}
function screenshotUrl(p){if(!p?.screenshot)return '';return p.screenshot.startsWith('data:image/')?p.screenshot:state.connection.url.replace(/\/$/,'')+p.screenshot}
function screenshots(){let d=data();return title('SCREEN CAPTURES','스크린샷','주요 화면과 상태를 진입 경로와 함께 기록합니다.',exportBtn())+demoBanner()+(d.pages.length?`<div class="section-heading"><h2>기록한 화면 <span class="badge-count">${d.pages.length}</span></h2><span class="demo-note">${state.mode==='demo'?'실제 캡처가 아닌 화면 표현 샘플':'실제 브라우저 캡처'}</span></div><div class="screenshot-grid">${d.pages.map(p=>`<button class="panel shot-card" style="padding:0;text-align:left" data-shot="${esc(p.id)}"><div class="shot-body">${state.mode==='demo'?sampleBrowser():p.screenshot?`<img loading="lazy" src="${esc(screenshotUrl(p))}" alt="${esc(p.name)} 스크린샷">`:'<div class="empty">캡처 없음</div>'}${state.mode==='demo'?'<span class="sample-label">SAMPLE · 실제 캡처 아님</span>':''}</div><div class="shot-meta"><strong>${esc(p.name)}</strong><small>${esc(p.path?.join(' → ')||p.url)}</small></div></button>`).join('')}</div>`:empty('저장된 스크린샷이 없습니다.','테스트 중 수집한 화면이 여기에 표시됩니다.'))}
function empty(h,p){return `<section class="panel empty">${icon('folder')}<h3>${h}</h3><p>${p}</p><button class="btn btn-outline" data-action="demo">샘플 결과 보기</button></section>`}
function features(){let d=data();return title('FUNCTION INVENTORY','기능 목록','관찰한 동작과 추론한 기능을 구분해 정리합니다.',exportBtn())+demoBanner()+`<section class="panel panel-table"><div class="panel-head"><h2>발견한 기능 <span class="badge-count">${d.features.length}</span></h2><span class="demo-note">동작 확인 여부를 별도 표시</span></div><div class="table-wrap"><table><thead><tr><th>기능명</th><th>설명</th><th>연결 화면</th><th>확인 상태</th><th>진입 경로</th></tr></thead><tbody>${d.features.map(f=>`<tr><td><span class="row-title">${icon('list')} ${esc(f.name)}</span></td><td>${esc(f.description)}</td><td>${f.pages}</td><td>${badge(f.status)}</td><td>${esc(f.path)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">발견한 기능이 없습니다.</td></tr>'}</tbody></table></div></section>`}
function cases(){let d=data(),cs=d.cases.filter(c=>(state.filter==='전체'||c.status===state.filter)&&`${c.name} ${c.id}`.toLowerCase().includes(state.query.toLowerCase()));return title('TEST CASES','테스트 케이스','실행 절차와 기대 결과, 실제 증거를 함께 확인하세요.',exportBtn())+demoBanner()+`<section class="panel panel-table"><div class="panel-head"><h2>테스트 케이스 <span class="badge-count">${d.cases.length}</span></h2><span class="demo-note">요구사항 없는 항목은 검토 필요로 분류</span></div><div class="table-toolbar"><div class="tabs">${['전체','통과','실패','검토 필요','제외됨'].map(s=>`<button class="${state.filter===s?'active':''}" data-filter="${s}">${s}</button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="caseSearch" placeholder="케이스 검색" aria-label="테스트 케이스 검색" value="${esc(state.query)}"></label></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>테스트 항목</th><th>기능</th><th>판정</th><th>실제 결과</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr class="rowclick" data-case="${esc(c.id)}"><td>${esc(c.id)}</td><td><span class="row-title">${esc(c.name)}</span></td><td>${esc(c.feature)}</td><td>${badge(c.status)}</td><td>${esc(c.actual)}</td><td>↗</td></tr>`).join('')||'<tr><td colspan="6" class="empty">일치하는 테스트 케이스가 없습니다.</td></tr>'}</tbody></table></div><div class="table-bottom"><span>생성 및 실행 근거는 상세 화면에서 확인할 수 있습니다.</span><span>${cs.length}개 표시</span></div></section>`}
function defects(){let d=data();return title('ISSUES & EVIDENCE','결함 리포트','확인된 실패와 검토가 필요한 후보를 증거로 구분합니다.',exportBtn())+demoBanner()+`<div class="report-summary"><div>전체 결함 및 후보<strong>${d.defects.length}</strong></div><div>검증 실패<strong>${d.defects.filter(x=>x.status==='검증 실패').length}</strong></div><div>검토 필요<strong>${d.defects.filter(x=>x.status!=='검증 실패').length}</strong></div></div><section class="panel panel-table"><div class="panel-head"><h2>발견 내역</h2><span class="demo-note">AI 판단만으로 결함을 확정하지 않습니다</span></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>결함 / 후보</th><th>영향도</th><th>판정</th><th>관련 화면</th><th></th></tr></thead><tbody>${d.defects.map(b=>`<tr class="rowclick" data-defect="${esc(b.id)}"><td>${esc(b.id)}</td><td><span class="row-title">${esc(b.name)}</span></td><td>${badge(b.severity)}</td><td>${badge(b.status)}</td><td>${esc(d.pages.find(p=>p.id===b.page)?.name||'—')}</td><td>↗</td></tr>`).join('')||'<tr><td colspan="6" class="empty">기록된 결함이 없습니다. 미실행 상태는 정상 판정이 아닙니다.</td></tr>'}</tbody></table></div></section>`}
function settings(){return title('ENGINE CONNECTION','워커 연결 설정','Sites의 관리 화면과 별도 Playwright 실행 서버를 연결합니다.')+`<div class="notice">실제 탐색에는 실행 중인 Playwright 워커가 필요합니다. 이 사이트 자체에는 브라우저 실행 환경이나 AI 키가 포함되어 있지 않습니다.</div><div class="settings-grid"><section class="panel settings-card"><h2>실행 서버 연결</h2><p>HTTPS API 주소와 워커의 접근 토큰을 입력하세요.</p><form id="settingsForm"><label class="field">워커 API URL<input id="workerUrl" type="url" placeholder="https://worker.example.com" value="${esc(state.connection.url||'')}" required><small>관리 화면의 출처를 워커의 ALLOWED_ORIGIN으로 등록해야 합니다.</small></label><label class="field">접근 토큰<input id="workerToken" type="password" placeholder="워커의 TRACEQA_TOKEN" autocomplete="off" value="${esc(state.connection.token||'')}" required><small>토큰은 현재 탭의 메모리에만 유지됩니다. 주소만 이 브라우저에 저장합니다.</small></label><button class="btn btn-dark" type="submit">${icon('link')} 연결 확인 및 저장</button><div class="connection-status" id="connectionStatus" role="status">${state.connected?'연결 확인 완료':'연결되지 않았습니다.'}</div></form><button class="btn btn-outline btn-sm" data-action="disconnect">연결 해제</button></section><section class="panel settings-card"><h2>Playwright 워커 시작하기</h2><p>제공된 워커를 별도 Node.js 서버에서 실행하세요. 공개할 때는 HTTPS와 접근 토큰이 필요합니다.</p><a class="btn btn-outline" href="traceqa-worker.zip" download>${icon('download')} 워커 소스 다운로드</a><pre class="codeblock">npm install
npx playwright install chromium
# .env.example을 참고해 환경 변수 설정
npm start</pre><p>AI 화면 분석은 서버의 <code>OPENAI_API_KEY</code> 설정 시 활성화됩니다. 미설정 시 DOM 기반 탐색으로 작동합니다.</p><button class="btn btn-text" data-action="guide">설치 및 연결 가이드 ${icon('arrow')}</button></section><section class="panel settings-card"><h2>탐색 정책</h2><div class="detail-row"><span>탐색 방식</span><strong>깊이 우선 재귀 탐색</strong></div><div class="detail-row"><span>깊이 제한</span><strong>없음</strong></div><div class="detail-row"><span>대상 범위</span><strong>같은 Origin</strong></div><div class="detail-row"><span>데이터 변경</span><strong>기본 제외</strong></div><p>새로운 화면 상태와 미처리 요소가 남아 있는 동안 탐색합니다. 반복 패턴, 실패, 제외 사유를 실행 로그에 기록합니다.</p></section><section class="panel settings-card"><h2>샘플 워크스페이스</h2><p>연결 없이 결과 화면과 재귀 탐색 흐름을 살펴보세요. 샘플은 실제 사이트를 방문하거나 AI를 호출하지 않습니다.</p><button class="btn btn-outline" data-action="demo">${icon('spark')} 샘플 결과 열기</button></section></div>`}
function modal(h,body,foot=''){if($('#modal').open)$('#modal').close();$('#modalContent').innerHTML=`<div class="modal-head"><h2>${h}</h2><button class="iconbtn" data-close aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot||'<button class="btn btn-dark" data-close>확인</button>'}</div>`;$('#modal').showModal();bindModal()}
function bindModal(){$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());$$('#modal [data-nav]').forEach(b=>b.onclick=()=>{$('#modal').close();go(b.dataset.nav)});$$('#modal [data-export]').forEach(b=>b.onclick=()=>downloadReport(b.dataset.export));$$('#modal [data-shot]').forEach(b=>b.onclick=()=>showShot(b.dataset.shot))}
function showShot(id){let p=data().pages.find(x=>x.id===id);if(!p)return;modal(esc(p.name),`${state.mode==='demo'?`<div class="notice">화면 표현용 샘플입니다. 실제 사이트 스크린샷이 아닙니다.</div><div class="screen-view">${sampleBrowser()}</div>`:p.screenshot?`<img class="screen-full" src="${esc(screenshotUrl(p))}" alt="${esc(p.name)}">`:'<p>이 화면의 캡처가 없습니다.</p>'}<h3>진입 경로</h3><p>${esc(p.path?.join(' → ')||p.url)}</p><h3>화면 정보</h3><p>${esc(p.url)} · 발견 요소 ${p.elements}개</p>`)}
function showCase(id){let c=data().cases.find(x=>x.id===id);if(!c)return;modal(`${esc(c.id)} · ${esc(c.name)}`,`${badge(c.status)}<h3>실행 절차</h3><div class="steps">${c.steps.map((s,i)=>`<div class="step"><b>${i+1}</b>${esc(s)}</div>`).join('')}</div><h3>기대 결과</h3><p>${esc(c.expected)}</p><h3>실제 결과</h3><p>${esc(c.actual)}</p><button class="btn btn-outline" data-shot="${esc(c.page)}">${icon('image')} 관련 화면 보기</button>`)}
function showDefect(id){let b=data().defects.find(x=>x.id===id);if(!b)return;modal(`${esc(b.id)} · ${esc(b.name)}`,`${badge(b.status)} ${badge(b.severity)}<h3>재현 절차</h3><ol>${b.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>기대 결과</h3><p>${esc(b.expected)}</p><h3>실제 결과</h3><p>${esc(b.actual)}</p><h3>실행 증거</h3><pre class="codeblock">${esc(b.evidence)}</pre><button class="btn btn-outline" data-shot="${esc(b.page)}">${icon('image')} 관련 화면 보기</button>`)}
function guide(){modal('TraceQA 사용 가이드',`<div class="help-grid"><div><strong>01 · 실행 서버 준비</strong><p>설정 화면에서 워커 소스를 다운로드합니다. Node.js 22 이상 환경에서 의존성과 Chromium을 설치합니다. README에 따라 토큰·허용 출처·허용 대상 도메인을 설정하세요.</p></div><div><strong>02 · AI 화면 이해 연결</strong><p>워커에 OPENAI_API_KEY와 이미지 입력을 지원하는 OPENAI_MODEL을 설정합니다. 키는 관리 화면에 입력하지 않습니다. AI 미연결 시 DOM 모드로 표시됩니다.</p></div><div><strong>03 · 연결 후 실제 탐색</strong><p>HTTPS 워커 URL과 접근 토큰을 저장하고 사이트 주소를 입력합니다. 각 화면에서 요소를 수집하고, 하위 경로 탐색 후 진입 경로를 재실행해 복원합니다.</p></div><div><strong>04 · 결과 해석</strong><p>통과는 명시된 자동 검증 항목에 대한 결과입니다. 업무 정확성을 확인하지 못한 동작은 검토 필요로 남깁니다. 실행이 중단되면 전체 탐색 완료로 표시하지 않습니다.</p></div></div>`,`<button class="btn btn-dark" data-nav="settings">워커 연결 설정</button>`)}
function bind(){$$('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});$$('[data-node]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.node;render()});$$('[data-shot]').forEach(b=>b.onclick=()=>showShot(b.dataset.shot));$$('[data-case]').forEach(b=>b.onclick=()=>showCase(b.dataset.case));$$('[data-defect]').forEach(b=>b.onclick=()=>showDefect(b.dataset.defect));$$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));if($('#urlForm'))$('#urlForm').onsubmit=startRun;if($('#settingsForm'))$('#settingsForm').onsubmit=connect;['historySearch','caseSearch'].forEach(id=>{let el=$('#'+id);if(el)el.oninput=()=>{let pos=el.selectionStart;state.query=el.value;render();let n=$('#'+id);n.focus();n.setSelectionRange(pos,pos)}})}
async function action(a){if(a==='demo'){state.mode='demo';state.sim=false;go('overview')}if(a==='real'){state.mode='real';go(state.connected?'runs':'settings')}if(a==='export'){modal('보고서 내보내기',`<p>${state.mode==='demo'?'샘플 보고서입니다. 실제 테스트 결과가 아니라는 표시가 포함됩니다.':'현재까지 수집된 결과를 내보냅니다. 중단·미검증 상태도 포함됩니다.'}</p><div class="report-summary"><div>화면<strong>${data().pages.length}</strong></div><div>테스트<strong>${data().cases.length}</strong></div><div>결함 / 후보<strong>${data().defects.length}</strong></div></div>`,`<button class="btn btn-outline" data-export="json">JSON</button><button class="btn btn-outline" data-export="csv">CSV</button><button class="btn btn-dark" data-export="html">HTML 보고서</button>`)}if(a==='guide')guide();if(a==='disconnect'){state.connected=false;state.connection={};localStorage.removeItem('traceqa-settings');render();toast('연결 정보를 삭제했습니다.')}if(a==='simulate')simulate();if(a==='pause'){if(state.mode==='demo'){state.paused=!state.paused;render()}else await control(state.paused?'resume':'pause')}if(a==='stop'){if(state.mode==='demo'){state.sim=false;clearInterval(window.simTimer);state.paused=false;toast('샘플 시뮬레이션을 중지했습니다.');render()}else await control('stop')}}
function simulate(){clearInterval(window.simTimer);state.sim=true;state.paused=false;state.logs=[];let i=0;const seq=[['메인 화면 분석','화면 영역과 조작 요소 12개 확인'],['상품 목록 클릭','클릭 전 요소 표시·가림 여부 확인'],['상품 목록 탐색','새 화면 기록 · 조작 요소 18개 발견'],['첫 번째 상품 클릭','상품 상세 화면 진입'],['이미지 확대 클릭','동일 URL의 새 모달 상태 기록'],['모달 탐색 완료','상위 상태 복원 및 확인'],['다음 상품 경로 탐색','기존 상태 중복 확인 후 다음 요소 선택'],['샘플 시뮬레이션 완료','실제 브라우저·AI 호출 없이 진행한 예시입니다.']];render();window.simTimer=setInterval(()=>{if(state.paused)return;if(!state.sim){clearInterval(window.simTimer);return}let x=seq[i++];state.logs.push({time:new Date().toLocaleTimeString('ko-KR'),text:x[0],detail:x[1]});if(i===seq.length){clearInterval(window.simTimer);state.sim=false;toast('샘플 흐름을 모두 확인했습니다.')}if(state.page==='runs')render()},1300)}
async function api(path,opt={}){let base=state.connection.url?.replace(/\/$/,'');if(!base)throw Error('워커 주소를 설정하세요.');let r=await fetch(base+path,{...opt,headers:{'Content-Type':'application/json',Authorization:'Bearer '+(state.connection.token||''),...opt.headers},signal:AbortSignal.timeout(15000)});let x=await r.json();if(!r.ok)throw Error(x.error||'서버 오류 '+r.status);return x}
async function connect(e){e.preventDefault();let url=$('#workerUrl').value.replace(/\/$/,''),token=$('#workerToken').value;try{if(new URL(url).protocol!=='https:')throw Error('배포된 관리 화면에서는 HTTPS 워커 주소를 사용하세요.');state.connection={url,token};$('#connectionStatus').textContent='연결 확인 중…';let h=await api('/health');if(h.service!=='traceqa-worker')throw Error('TraceQA 워커 응답이 아닙니다.');state.connected=true;localStorage.setItem('traceqa-settings',JSON.stringify({url}));state.mode='real';render();toast('연결 완료 · '+(h.ai?'AI + DOM 모드':'DOM 모드 · AI 키 미설정'))}catch(err){state.connected=false;$('#connectionStatus').classList.add('error');$('#connectionStatus').textContent='연결 실패: '+err.message}}
async function startRun(e){e.preventDefault();state.target=$('#targetUrl').value;if(!state.connected){modal('실제 탐색을 위한 워커 연결',`<p><strong>${esc(state.target)}</strong> 사이트를 탐색하려면 Playwright 실행 서버를 먼저 연결해야 합니다.</p><p>관리 화면만으로 외부 사이트의 DOM을 읽거나 브라우저를 자동 조작할 수는 없습니다. 제공된 워커를 실행하고 연결하면 실제 테스트를 시작할 수 있습니다.</p>`,`<button class="btn btn-outline" data-close>취소</button><button class="btn btn-dark" data-nav="settings">워커 연결하기</button>`);return}try{let u=new URL(state.target);if(!['https:','http:'].includes(u.protocol))throw Error('HTTP 또는 HTTPS 주소를 입력하세요.');let run=await api('/runs',{method:'POST',body:JSON.stringify({url:state.target})});state.run=run;state.mode='real';state.paused=false;go('runs');clearInterval(window.pollTimer);window.pollTimer=setInterval(pollRun,2000);toast('실제 테스트를 시작했습니다.')}catch(err){toast('실행 실패: '+err.message)}}
async function pollRun(){if(!state.run)return;try{state.run=await api('/runs/'+state.run.id);if(!['실행 중','일시정지'].includes(state.run.status))clearInterval(window.pollTimer);if(state.mode==='real'&&!$('#modal').open)render()}catch(err){clearInterval(window.pollTimer);toast('상태 조회 실패: '+err.message)}}
async function control(action){try{state.run=await api('/runs/'+state.run.id+'/'+action,{method:'POST',body:'{}'});state.paused=state.run.status==='일시정지';render()}catch(err){toast(err.message)}}
function saveBlob(text,type,name){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadReport(format){let d=data(),sample=state.mode==='demo',report={tool:'TraceQA',sample,generatedAt:new Date().toISOString(),status:sample?'샘플 · 실제 실행 아님':state.run?.status||'미실행',...d};let name='traceqa-'+(sample?'sample-':'')+new Date().toISOString().slice(0,10);if(format==='json')saveBlob(JSON.stringify(report,null,2),'application/json',name+'.json');if(format==='csv'){let rows=[['ID','테스트 항목','기능','판정','기대 결과','실제 결과','자료 구분'],...d.cases.map(c=>[c.id,c.name,c.feature,c.status,c.expected,c.actual,sample?'샘플':'실제 실행'])];let safe=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};saveBlob('\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8',name+'.csv')}if(format==='html'){let html=`<!doctype html><html lang="ko"><meta charset="utf-8"><title>TraceQA 보고서</title><style>body{font:14px sans-serif;max-width:1000px;margin:40px auto;padding:20px;color:#243b29}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:12px;text-align:left}h2{margin-top:32px}small{color:#777}pre{white-space:pre-wrap}article{border:1px solid #ddd;padding:15px;margin:15px 0}</style><h1>TraceQA 테스트 보고서</h1><p>${sample?'샘플 보고서 · 실제 테스트 결과가 아닙니다.':esc(report.status)}</p><small>${esc(report.generatedAt)}</small><h2>탐색 범위</h2><p>화면 ${d.pages.length}개 · 테스트 ${d.cases.length}개 · 결함 및 후보 ${d.defects.length}건</p><h2>발견 화면</h2><ul>${d.pages.map(p=>`<li>${esc(p.name)} · ${esc(p.url)} · ${esc(p.status)}</li>`).join('')}</ul><h2>테스트 케이스</h2><table><tr><th>ID</th><th>항목</th><th>판정</th><th>실제 결과</th></tr>${d.cases.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.name)}</td><td>${esc(c.status)}</td><td>${esc(c.actual)}</td></tr>`).join('')}</table><h2>결함 및 후보</h2>${d.defects.map(b=>`<article><h3>${esc(b.id)} · ${esc(b.name)}</h3><p>${esc(b.status)}</p><ol>${b.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>기대: ${esc(b.expected)}</p><p>실제: ${esc(b.actual)}</p><pre>${esc(b.evidence)}</pre></article>`).join('')}<h2>실행 로그 및 제외 사유</h2><ul>${d.logs.map(l=>`<li>${esc(l.text)} · ${esc(l.detail)}</li>`).join('')}</ul></html>`;saveBlob(html,'text/html;charset=utf-8',name+'.html')}toast('보고서를 다운로드했습니다.');$('#modal').close()}
$('#connectBtn').onclick=()=>go('settings');$('#helpBtn').onclick=guide;$('#workspace').onclick=()=>toast('현재 개인 워크스페이스를 사용 중입니다.');$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});render();
